480	// configured checkpoint_remote URL and updates the local branch.
481	// Returns an error if the fetch fails or no checkpoint_remote is configured.
482	func FetchMetadataFromCheckpointRemote(ctx context.Context) error {
483		configured := remote.Configured(ctx)
484		if !configured {
485			return errors.New("no checkpoint_remote configured")
486		}
487		checkpointURL, err := remote.FetchURL(ctx)
488		if err != nil {
489			return fmt.Errorf("checkpoint_remote configured but could not resolve URL: %w", err)
490		}
491	
492		if err := strategy.FetchMetadataBranch(ctx, checkpointURL); err != nil {
493			return fmt.Errorf("failed to fetch from checkpoint remote: %w", err)
494		}
495		return nil
496	}
