498	// resolveCheckpointFetchTarget returns the fetch target for checkpoint data.
499	// It prefers the effective URL resolved by checkpoint/remote.FetchURL, which is
500	// the source of truth for checkpoint fetch location. If URL resolution fails, it
501	// falls back to the origin remote name so callers can still attempt a fetch.
502	func resolveCheckpointFetchTarget(ctx context.Context) string {
503		url, err := remote.FetchURL(ctx)
504		if err == nil && url != "" {
505			return url
506		}
507		return "origin"
508	}
