510	// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
511	// Uses "git fetch <target> <hash>" which goes through normal credential helpers,
512	// unlike fetch-pack which bypasses them. Requires the server to support
513	// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
514	//
515	// The fetch target is resolved via resolveCheckpointFetchTarget, which defers to
516	// checkpoint/remote.FetchURL for the effective remote URL when available.
517	//
518	// If fetching by hash fails, falls back to a full metadata branch fetch.
519	func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
520		if len(hashes) == 0 {
521			return nil
522		}
523	
524		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
525		defer cancel()
526	
527		fetchTarget := resolveCheckpointFetchTarget(ctx)
528	
529		hashStrs := make([]string, len(hashes))
530		for i, h := range hashes {
531			hashStrs[i] = h.String()
532		}
533	
534		if fetchErr := remote.FetchBlobs(ctx, fetchTarget, hashStrs); fetchErr != nil {
535			logging.Debug(ctx, "fetch-by-hash failed, falling back to full metadata fetch",
