// BootstrapMetadataFromCheckpointRemote populates the local metadata branch from a
// configured checkpoint_remote when no local or origin-tracked branch exists.
//
// This prevents `entire enable` on a second device from creating an empty orphan
// branch that conflicts with the real metadata branch already stored in the
// checkpoint remote — the orphan would otherwise leave `entire checkpoint list`
// empty and cause a non-fast-forward rejection on the next fetch (issue #1374).
//
// The local branch is known to be absent when this is called, so
// FetchMetadataBranch's SafelyAdvanceLocalRef sets the ref directly to the fetched
// tip (no replay, no empty commit). Returns true when a non-empty branch was
// fetched and the local ref now points at it. All failure modes are non-fatal and
// return (false, nil) so setup can fall back to creating an orphan.
func BootstrapMetadataFromCheckpointRemote(ctx context.Context, repo *git.Repository) (bool, error) {
	url, ok := resolveCheckpointRemoteURL(ctx)
	if !ok {
		return false, nil
	}
	if err := FetchMetadataBranch(ctx, url); err != nil {
		logging.Debug(ctx, "checkpoint-remote: metadata bootstrap fetch failed; will create orphan",
			slog.String("error", err.Error()))
		return false, nil
	}
	ref, err := repo.Reference(checkpoint.ResolveCommittedRefs(ctx).Primary, true)
	if err != nil {
		return false, nil
	}
	isEmpty, err := isEmptyMetadataBranch(repo, ref)
	if err != nil || isEmpty {
		return false, nil
	}
	fmt.Fprintf(os.Stderr, "✓ Fetched metadata branch '%s' from checkpoint remote\n", paths.MetadataBranchName)
	return true, nil
}

// HealEmptyOrphanMetadataFromCheckpointRemote replaces a local metadata branch that
// is an empty orphan (the bug behind issue #1374) with the real branch fetched from
// a configured checkpoint_remote. This repairs second-device repos that were enabled
// before BootstrapMetadataFromCheckpointRemote existed and were left with an empty
// orphan disjoint from the remote history.
//
// It force-sets the local ref to the fetched tip rather than routing through
// SafelyAdvanceLocalRef: the orphan is disconnected from the real branch, so a safe
// advance would cherry-pick the empty-tree orphan commit onto the real tip, leaving
// a stray empty commit. Discarding the empty orphan is always correct here.
//
// Returns true when the branch was healed. All failure modes are non-fatal and
// return (false, nil) except a failed ref write, which is surfaced.
func HealEmptyOrphanMetadataFromCheckpointRemote(ctx context.Context, repo *git.Repository, localRef *plumbing.Reference) (bool, error) {
	isEmpty, err := isEmptyMetadataBranch(repo, localRef)
	if err != nil {
		return false, fmt.Errorf("failed to check metadata branch contents: %w", err)
	}
	if !isEmpty {
		return false, nil
	}
	url, ok := resolveCheckpointRemoteURL(ctx)
	if !ok {
		return false, nil
	}

	refs := checkpoint.ResolveCommittedRefs(ctx)
	if !refs.Primary.IsBranch() {
		return false, nil
	}
	tmpRef := plumbing.ReferenceName(FetchTmpRefPrefix + refs.Primary.Short())
	defer func() { _ = repo.Storer.RemoveReference(tmpRef) }() //nolint:errcheck // cleanup is best-effort

	if err := fetchURLIntoTmpRef(ctx, url, refs.Primary.String(), tmpRef.String(), "metadata branch", true); err != nil {
		logging.Debug(ctx, "checkpoint-remote: empty-orphan heal fetch failed",
			slog.String("error", err.Error()))
		return false, nil
	}

	fetchedRef, err := repo.Reference(tmpRef, true)
	if err != nil {
		return false, nil
	}
	fetchedIsEmpty, err := isEmptyMetadataBranch(repo, fetchedRef)
	if err != nil || fetchedIsEmpty {
		return false, nil
	}

	if err := setRefHash(repo, refs.Primary, fetchedRef.Hash()); err != nil {
		return false, fmt.Errorf("failed to replace empty orphan metadata branch: %w", err)
	}
	MirrorCommittedMetadataRefBestEffort(ctx, repo)
	fmt.Fprintf(os.Stderr, "✓ Replaced empty metadata branch '%s' with data from checkpoint remote\n", paths.MetadataBranchName)
	return true, nil
}

